// ============================================================
// Merge Hindi translations into messages/hi.json
// ============================================================
function applyTranslations(lang, translations) {
  const langPath = `messages/${lang}.json`;
  const data = JSON.parse(fs.readFileSync(langPath, 'utf8'));

  // Deep copy English seasonal structure as base (preserves slug, citations, relatedEmergency, href values)
  const seasonalBase = JSON.parse(JSON.stringify(enSeasonal));

  // Apply translations (only the translated fields will be overwritten)
  for (const [slug, translation] of Object.entries(translations)) {
    if (seasonalBase[slug]) {
      seasonalBase[slug] = { ...seasonalBase[slug], ...translation };
    } else {
      seasonalBase[slug] = translation;
    }
  }

  data.seasonal = { ...data.seasonal, ...seasonalBase };
  fs.writeFileSync(langPath, JSON.stringify(data, null, 2));
  console.log(`✓ Hindi translations applied to ${langPath}`);
}

applyTranslations('hi', hi);